<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Throwable; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Pterodactyl\Facades\Activity; use Pterodactyl\Services\Dezerx\RecycleBin; use Pterodactyl\Models\Dezerx\RecycledFile; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonDeleteRequest; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class RecycleBinController extends ClientApiController { public function __construct(private readonly RecycleBin $bin) { parent::__construct(); } public function index(AddonRequest $request, Server $server): JsonResponse { return new JsonResponse([ 'retention_days' => RecycleBin::retentionDays(), 'items' => $this->bin->contents($server)->map(fn (RecycledFile $item) => [ 'id' => $item->id, 'name' => $item->name, 'root' => $item->root, 'path' => $item->originalPath(), 'is_directory' => $item->is_directory, 'size' => $item->size, 'deleted_at' => $item->deleted_at?->toAtomString(), 'expires_at' => $item->expires_at?->toAtomString(), ])->values(), ]); } public function restore(AddonDeleteRequest $request, Server $server, int $item): JsonResponse { $record = $this->find($server, $item); try { $destination = $this->bin->restore($server, $record); } catch (Throwable $exception) { return new JsonResponse([ 'errors' => [['code' => 'RestoreFailed', 'detail' => $exception->getMessage()]], ], 500); } Activity::event('server:file.restore') ->property(['file' => $record->name, 'to' => $destination]) ->log(); return new JsonResponse(['path' => $destination]); } public function restoreAll(AddonDeleteRequest $request, Server $server): JsonResponse { $restored = 0; $failed = 0; foreach ($this->bin->contents($server) as $record) { try { $this->bin->restore($server, $record); $restored++; } catch (Throwable) { $failed++; } } Activity::event('server:file.restore')->property(['restored' => $restored])->log(); return new JsonResponse(['restored' => $restored, 'failed' => $failed]); } public function destroy(AddonDeleteRequest $request, Server $server, int $item): JsonResponse { $record = $this->find($server, $item); $this->bin->purge($server, $record); Activity::event('server:file.delete') ->property(['directory' => $record->root, 'files' => [$record->name]]) ->log(); return new JsonResponse([], JsonResponse::HTTP_NO_CONTENT); } public function destroyAll(AddonDeleteRequest $request, Server $server): JsonResponse { $emptied = 0; foreach ($this->bin->contents($server) as $record) { $this->bin->purge($server, $record); $emptied++; } Activity::event('server:file.delete')->property(['emptied' => $emptied])->log(); return new JsonResponse(['deleted' => $emptied]); } private function find(Server $server, int $item): RecycledFile { $record = RecycledFile::query() ->where('server_id', $server->id) ->whereKey($item) ->first(); if ($record === null) { throw new NotFoundHttpException('That is not in this server\'s recycle bin.'); } return $record; } } 